1	package cmd
2	
3	import (
4		"fmt"
5		"os"
6		"strings"
7	
8		"github.com/synacktiv/octoscan/common"
9		"github.com/synacktiv/octoscan/core"
10	
11		"github.com/docopt/docopt-go"
12		"github.com/fatih/color"
13		"github.com/rhysd/actionlint"
14	)
15	
16	var usageScan = `octoscan
17	
18	Usage:
19		octoscan scan [options] --list-rules
20		octoscan scan [options] <target>
21		octoscan scan [options] <target> [--debug-rules --filter-triggers=<triggers> --filter-run --ignore=<pattern> ((--disable-rules | --enable-rules ) <rules>) --config-file <config>]
22	
23	Options:
24		-h, --help
25		-v, --version
26		-d, --debug
27		--verbose
28		--format <format>  				Output format, json, sarif or custom template to format error messages in Go template syntax. See https://github.com/rhysd/actionlint/tree/main/docs/usage.md#format
29		--oneline  					Use one line per one error. Useful for reading error messages from programs
30	
31	Args:
32		<target>					Target File or directory to scan
33		--filter-triggers <triggers>			Scan workflows with specific triggers (comma separated list: "push,pull_request_target" or pre-configured: external/allnopr)
34		--filter-run					Search for expression injection only in run shell scripts.
35		--ignore <pattern>				Regular expression matching to error messages you want to ignore.
36		--disable-rules <rules>				Disable specific rules. Split on ","
37		--enable-rules <rules>				Enable specific rules, this will disable all other rules. Split on ","
38		--debug-rules					Enable debug rules.
39		--config-file <config>				Config file.
40	
41	Examples:
42		$ octoscan scan ci.yml --disable-rules shellcheck,local-action --filter-triggers external
43	`
44	
45	func checkInternet(args docopt.Opts) {
46		checkInternet := true
47	
48		if args["--enable-rules"] != false && !strings.Contains(args["<rules>"].(string), "repo-jacking") {
49			checkInternet = false
50		}
51	
52		if args["--disable-rules"] != false && strings.Contains(args["<rules>"].(string), "repo-jacking") {
53			checkInternet = false
54		}
55	
56		if checkInternet {
57			err := common.IsInternetAvailable()
58			if err != nil {
59				common.Log.Info("Could not connect to Internet, skipping \"repo-jacking\" rule.")
60	
61				core.Internetavailable = false
62			}
63		}
64	}
65	
66	func runScanner(args docopt.Opts) int {
67		var errs []*actionlint.Error
68		opts := setScannerArgs(args)
69	
70		checkInternet(args)
71	
72		l, err := actionlint.NewLinter(os.Stdout, &opts)
73		if err != nil {
74			return common.ExitStatusFailure
75		}
76	
77		file, _ := args.String("<target>")
78	
79		if common.IsDirectory(file) {
80			octoLinter := &core.OctoLinter{Linter: *l}
81			errs, err = octoLinter.LintRepositoryRecurse(file)
82		} else {
83			errs, err = l.LintFile(file, nil)
84		}
85	
86		if err != nil {
87			common.Log.Error(err)
88	
89			return common.ExitStatusFailure
90		}
91	
92		if args["--format"] != nil {
93			switch format := args["--format"].(string); format {
94			case "json":
95				opts.Format = "{{json .}}"
96			case "sarif":
97				opts.Format = string(common.SarifTemplate)
98			default:
99				opts.Format = format
100			}
101			// Now we can use our own formatter on all the errors.
102			err = core.DisplayErrors(os.Stdout, opts.Format, errs)
103		}
104	
105		if err != nil {
106			common.Log.Error(err)
107	
108			return common.ExitStatusFailure
109		}
110	
111		if len(errs) > 0 {
112			return common.ExitStatusSuccessProblemFound // Linter found some issues, yay!
113		}
114	
115		return common.ExitStatusSuccessNoProblem
116	}
117	
118	func listRules() int {
119		yellow := color.New(color.FgYellow)
120		core.DebugRules = true
121		rules := &[]actionlint.Rule{}
122	
123		common.Log.Info("Available rules")
124	
125		availableRules := core.OnRulesCreated(*rules)
126		for _, rule := range availableRules {
127			//nolint
128			fmt.Printf("- %v\n", yellow.Sprintf(rule.Name()))
129			//nolint
130			fmt.Printf("\t%v\n", rule.Description())
131		}
132	
133		return common.ExitStatusSuccessNoProblem
134	}
135	
136	func setCoreParameter(args docopt.Opts) {
137		if args["--filter-triggers"] != nil {
138			if args["--filter-triggers"].(string) == "external" {
139				core.FilterTriggers = common.TriggerWithExternalData
140			} else if args["--filter-triggers"].(string) == "allnopr" {
141				core.FilterTriggers = common.AllTriggers
142			} else {
143				core.FilterTriggers = strings.Split(args["--filter-triggers"].(string), ",")
144			}
145		}
146	
147		if v, _ := args.Bool("--disable-rules"); v {
148			core.FilterRules(false, strings.Split(args["<rules>"].(string), ","))
149		}
150	
151		if v, _ := args.Bool("--enable-rules"); v {
152			core.FilterRules(true, strings.Split(args["<rules>"].(string), ","))
153		}
154	
155		if v, _ := args.Bool("--debug-rules"); v {
156			core.DebugRules = true
157		}
158	
159		if v, _ := args.Bool("--filter-run"); v {
160			core.FilterRun = true
161		}
162	}
163	
164	func setScannerArgs(args docopt.Opts) actionlint.LinterOptions {
165		var opts actionlint.LinterOptions
166	
167		if d, _ := args.Bool("--debug"); d {
168			opts.Debug = true
169		}
170	
171		if v, _ := args.Bool("--verbose"); v {
172			opts.Verbose = true
173		}
174	
175		if v, _ := args.Bool("--oneline"); v {
176			opts.Oneline = true
177		}
178	
179		/*
180			This is a hacky trick to disable the formatter of actionlint otherwise it will use
181			a new formatter for each repo and this not what we want. We want to use the same
182			formatter for all the repo. It's far from being perfect but I don't know how to do it.
183		*/
184		if args["--format"] != nil {
185			opts.Format = "{{\"\"}}"
186		}
187	
188		setCoreParameter(args)
189	
190		opts.Shellcheck = "shellcheck"
191		// Add default ignore pattern
192		// by default actionlint add error when parsing Workflows files
193		opts.IgnorePatterns = append(opts.IgnorePatterns, common.SyntaxCheckErrors...)
194	
195		if args["--ignore"] != nil {
196			opts.IgnorePatterns = append(opts.IgnorePatterns, args["--ignore"].(string))
197		}
198	
199		opts.LogWriter = os.Stderr
200		opts.OnRulesCreated = core.OnRulesCreated
201	
202		if args["--config-file"] != false {
203			opts.ConfigFile = args["<config>"].(string)
204		}
205	
206		return opts
207	}
208	
209	func Scan(inputArgs []string) int {
210		parser := &docopt.Parser{}
211		args, _ := parser.ParseArgs(usageScan, inputArgs, "")
212	
213		// debug
214		// common.Log.Info(args)
215	
216		if v, _ := args.Bool("--list-rules"); v {
217			return listRules()
218		}
219	
220		return runScanner(args)
221	
222	}
223

