func TestUnpinnedActionSplitUsesRef(t *testing.T) {
	tests := []struct {
		name   string
		spec   string
		quoted bool
		kind   usesKind
		ref    string
		offset int
	}{
		{
			name:   "quoted tag step",
			spec:   "actions/checkout@v4",
			quoted: true,
			kind:   usesKindTag,
			ref:    "v4",
			offset: len("actions/checkout@") + 1, // +1 for the opening quote
		},
		{
			name: "plain tag step",
			spec: "octo/release@2",
			kind: usesKindTag,
			ref:  "2",
			// split on the last "@"
			offset: len("octo/release@"),
		},
		{
			name: "ref containing a slash keeps the last at split",
			spec: "octo/repo/.github/workflows/wf.yml@release/v2",
			kind: usesKindTag,
			ref:  "release/v2",
			offset: len("octo/repo/.github/workflows/wf.yml@"),
		},
		{
			name:   "shortened 7 hex SHA",
			spec:   "octo/action@abcdef7",
			kind:   usesKindShortSHA,
			ref:    "abcdef7",
			offset: len("octo/action@"),
		},
		{
			name:   "shortened 39 hex SHA",
			spec:   "octo/action@" + hex39,
			kind:   usesKindShortSHA,
			ref:    hex39,
			offset: len("octo/action@"),
		},
		{
			name:   "full length 40 lowercase hex SHA is pinned",
			spec:   "octo/action@" + hex40,
			kind:   usesKindPinned,
			ref:    hex40,
			offset: len("octo/action@"),
		},
		{
			name:   "uppercase 40 hex SHA is not pinned",
			spec:   "octo/action@0123456789ABCDEF0123456789ABCDEF01234567",
			kind:   usesKindTag,
			ref:    "0123456789ABCDEF0123456789ABCDEF01234567",
			offset: len("octo/action@"),
		},
		{
			name:   "local reference has no at sign and must not pollute the offset",
			spec:   "./.github/workflows/reusable.yml",
			kind:   usesKindLocal,
			ref:    "",
			offset: 0,
		},
		{
			name: "job level local reference",
			spec: "./local/action",
			kind: usesKindLocal,
		},
		{
			name: "docker digest at sign belongs to the scheme",
			spec: "docker://alpine@sha256:" + hex64,
			kind: usesKindDocker,
		},
		{
			name: "docker image without digest",
			spec: "docker://alpine:3.20",
			kind: usesKindDocker,
		},
		{
			name: "spec without any ref",
			spec: "octo/action",
			kind: usesKindLocal,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			kind, ref, offset := splitUsesRef(&actionlint.String{Value: tc.spec, Quoted: tc.quoted})
			if kind != tc.kind {
				t.Fatalf("kind: want %d, got %d", tc.kind, kind)
			}
			if ref != tc.ref {
				t.Fatalf("ref: want %q, got %q", tc.ref, ref)
			}
			if offset != tc.offset {
				t.Fatalf("offset: want %d, got %d", tc.offset, offset)
			}
		})
	}
}

func TestUnpinnedActionRuleOnTestdata(t *testing.T) {
	src, err := os.ReadFile("../../testdata/unpinned-actions.yml")
	if err != nil {
		t.Fatal(err)
	}

	workflow, parseErrs := actionlint.Parse(src)
	if len(parseErrs) != 0 {
		t.Fatalf("unexpected parse errors: %v", parseErrs)
	}

	rule := NewRuleUnpinnedAction(nil)
	visitor := actionlint.NewVisitor()
	visitor.AddPass(rule)

	if err := visitor.Visit(workflow); err != nil {
		t.Fatal(err)
	}

	errs := rule.Errs()
	if len(errs) != 3 {
		t.Fatalf("want exactly 3 findings, got %d: %v", len(errs), errs)
	}

	wantRefs := map[string]string{
		"v4":      "tag",
		"2":       "tag",
		"abcdef7": "short-sha",
	}

	lines := splitLines(src)

	for _, e := range errs {
		if e.Kind != "unpinned-action" {
			t.Fatalf("unexpected rule kind %q", e.Kind)
		}

		fields := e.GetTemplateFields(src)

		// the underline must start exactly at the first character of the ref
		line := lines[e.Line-1]
		end := fields.Column - 1 + len(wantRefKey(e.Message))
		got := line[fields.Column-1 : end]
		if _, ok := wantRefs[got]; !ok {
			t.Fatalf("underline does not cover the ref: line %q, column %d, got %q", line, fields.Column, got)
		}

		// end column is driven by the ref length, the underline spans the ref only
		if fields.EndColumn != fields.Column+len(got)-1 {
			t.Fatalf("end column: want %d, got %d", fields.Column+len(got)-1, fields.EndColumn)
		}

		switch wantRefs[got] {
		case "short-sha":
			assertContains(t, e.Message, "shortened commit SHA")
		case "tag":
			assertContains(t, e.Message, "mutable tag or branch")
		}

		delete(wantRefs, got)
	}

	if len(wantRefs) != 0 {
		t.Fatalf("missing findings for refs %v", wantRefs)
	}
}

const (
	hex40 = "0123456789abcdef0123456789abcdef01234567"
	hex39 = "0123456789abcdef0123456789abcdef0123456"
	hex64 = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
)

func wantRefKey(message string) string {
	// messages quote the ref as %q, extract the last quoted segment
	for i := len(message) - 2; i >= 0; i-- {
		if message[i] == '"' {
			return message[i+1 : len(message)-1]
		}
	}
	return ""
}

func splitLines(src []byte) []string {
	var lines []string
	start := 0
	for i, b := range src {
		if b == '\n' {
			lines = append(lines, string(src[start:i]))
			start = i + 1
		}
	}
	if start < len(src) {
		lines = append(lines, string(src[start:]))
	}
	return lines
}

func assertContains(t *testing.T, s, sub string) {
	t.Helper()
	if !contains(s, sub) {
		t.Fatalf("message %q does not contain %q", s, sub)
	}
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

