			t.Fatalf("unexpected rule kind %q", e.Kind)
		}

		fields := e.GetTemplateFields(src)

		// the underline must start exactly at the first character of the ref
		line := lines[e.Line-1]
		end := fields.Column - 1 + len(wantRefKey(e.Message))
		got := line[fields.Column-1 : end]
		if _, ok := wantRefs[got]; !ok {
			t.Fatalf("underline does not cover the ref: line %q, column %d, got %q", line, fields.Column, got)
		}

		// end column is driven by the ref length, the underline spans the ref only
		if fields.EndColumn != fields.Column+len(got)-1 {
			t.Fatalf("end column: want %d, got %d", fields.Column+len(got)-1, fields.EndColumn)
		}

		switch wantRefs[got] {
		case "short-sha":
			assertContains(t, e.Message, "shortened commit SHA")
		case "tag":
			assertContains(t, e.Message, "mutable tag or branch")
		}

		delete(wantRefs, got)
	}

	if len(wantRefs) != 0 {
		t.Fatalf("missing findings for refs %v", wantRefs)
	}
